def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = int(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    # If no one is alive, spend minimally but still keep survival.
    if not alive_opps:
        return min(budget, DAILY_SALARY * 0.4)

    # Read only yesterday immediate behavior from previous_trace.
    prev_bids = []
    for _, opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        if prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev.get('bid', 0.0)))
            except Exception:
                pass

    # Pressure estimate from yesterday.
    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Supply-based aggressiveness: if supply is barely above requirement, ensure we win.
    # With requirement 13 and supply range 15-25, low supply days are 15-16.
    low_supply = supply <= (WATER_REQ + 2.0)  # 15-16

    # If we are already in danger, bid more.
    danger = (hp <= 2) or (no_water_days >= 2)

    # Base bid aims to beat typical high bids seen yesterday but not always match the max.
    # Cindy averaged high and survived; Bob also survived with high bids.
    # We target slightly above a fraction of yesterday's highest bid.
    target = 0.0
    if highest_prev_bid > 0.0:
        # If yesterday someone was paying near our salary, we must not underbid.
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            target = highest_prev_bid * 0.85 + 5.0
        else:
            target = max(DAILY_SALARY * 0.5, highest_prev_bid + 2.0)
    else:
        target = DAILY_SALARY * 0.55

    # Adjust for our state and supply.
    if low_supply:
        target *= 1.15
    if danger:
        target *= 1.25

    # Keep bid within budget and avoid overspending.
    # Also cap at a reasonable multiple of salary; budget can be small.
    max_reasonable = DAILY_SALARY * 1.2
    bid = min(budget, max_reasonable, target)

    # Ensure non-negative and at least something if budget allows.
    if bid < 0.0:
        bid = 0.0

    # If we still have budget but bid is too low relative to danger, bump.
    if danger and budget > 0.0 and bid < DAILY_SALARY * 0.7:
        bid = min(budget, DAILY_SALARY * 0.9)

    return float(bid)

