        return 0.0

    alive_opponents = []
    prev_bids = []
    strong_pressure = 0.0
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if opp.get('budget', 0) > DAILY_SALARY * 2:
                    strong_pressure = max(strong_pressure, float(bid))

    if not alive_opponents:
        return float(min(budget, DAILY_SALARY * 0.35))

    slots = int(supply / WATER_REQ)
    alive_count = len(alive_opponents) + 1
    scarcity = alive_count - slots

    max_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    urgent = hp <= 3 or no_water_days >= 2
    pressured = hp <= 5 or no_water_days >= 1

    if slots >= alive_count:
        base = DAILY_SALARY * 0.18
        if urgent:
            base = DAILY_SALARY * 0.42
        elif pressured:
            base = DAILY_SALARY * 0.28
        bid = base
    elif scarcity <= 1:
        if urgent:
            bid = max(DAILY_SALARY * 0.82, max_prev + 2.0)
        elif pressured:
            bid = max(DAILY_SALARY * 0.58, avg_prev * 0.72 + 3.0)
        else:
            bid = DAILY_SALARY * 0.34
    else:
        if urgent:
            bid = max(DAILY_SALARY * 0.92, strong_pressure + 3.0, max_prev * 0.9)
        elif pressured:
            bid = max(DAILY_SALARY * 0.62, avg_prev * 0.68 + 2.0)
        else:
            bid = DAILY_SALARY * 0.22

    if day >= 8:
        if hp <= 4:
            bid = max(bid, DAILY_SALARY * 0.88)
        else:
            bid = max(bid, DAILY_SALARY * 0.45)

    if budget < DAILY_SALARY:
        if urgent:
            bid = max(bid, budget * 0.9)
        else:
            bid = min(bid, budget * 0.55)

    bid = min(bid, budget)
    if bid < 0:
        bid = 0.0
    return float(bid)

