            if prev_trace and prev_trace.get('bid') is not None and prev_trace['bid'] > 0:
                yesterday_bids.append(prev_trace['bid'])

    bid = MY_DAILY_SALARY * 0.6

    if my_status['hp'] <= 2 or my_status['no_water_days'] > 0:
        bid = MY_DAILY_SALARY * 0.95
        return min(my_status['budget'], max(1.0, bid))

    if not alive_opponents:
        bid = MY_DAILY_SALARY * 0.1
        return min(my_status['budget'], max(1.0, bid))

    if yesterday_bids:
        max_yesterday_bid = max(yesterday_bids)
        avg_yesterday_bid = sum(yesterday_bids) / len(yesterday_bids)

        bid = max(max_yesterday_bid + 5.0, avg_yesterday_bid * 1.1)

        if my_status['hp'] < 5:
            bid = max(bid, MY_DAILY_SALARY * 0.75)
        elif my_status['hp'] >= 8:
            bid = min(bid, MY_DAILY_SALARY * 0.65)

        if day_context['day'] > EPISODE_DAYS * 0.7:
            bid = max(bid, MY_DAILY_SALARY * 0.88)
        elif day_context['day'] < EPISODE_DAYS * 0.3:
            bid = min(bid, MY_DAILY_SALARY * 0.58)

    else:
        bid = MY_DAILY_SALARY * 0.65

        if day_context['day'] > EPISODE_DAYS * 0.7:
            bid = MY_DAILY_SALARY * 0.8
        elif day_context['day'] < EPISODE_DAYS * 0.3:
            bid = MY_DAILY_SALARY * 0.5

    sorted_reqs = sorted(all_water_requirements)
    potential_winners_count = 0
    temp_supply = day_context['supply']

    for req in sorted_reqs:
        if temp_supply >= req:
            potential_winners_count += 1
            temp_supply -= req
        else:
            break

    total_players = len(all_water_requirements)

    if potential_winners_count < total_players:
        bid *= 1.15
    elif potential_winners_count > total_players:
        bid *= 0.85

    bid = min(my_status['budget'], max(1.0, bid))

    return bid

